E['en']['3']=dict(be,les='LESSON 10.3',lt='Reset, reflog and common errors',other='Reset وreflog والأخطاء الشائعة',
 obj=['Explain soft, mixed and hard reset.','Recover with reflog.','Fix five common errors.'],pre='Lesson 10.2.',intro='Reset moves your branch backwards. It is powerful, so learn its three modes.',
 exp=['<code>git reset --soft HEAD~1</code> undoes the last commit but keeps the changes <b>staged</b>.','<code>git reset HEAD~1</code> (mixed, the default) keeps the changes in files but <b>unstaged</b>.','<code>git reset --hard HEAD~1</code> undoes the commit <b>and discards the changes</b>. Use it only on local work you do not need.','<b>Never reset commits you already pushed</b>; use revert.','<code>git reflog</code> lists where HEAD has been, including commits that look lost. Use <code>git reset --hard ID</code> or <code>git switch -c rescue ID</code> to get back (Figure 1). Reflog is local and entries expire after some weeks.','<b>Common errors.</b> “Author identity unknown” → set <code>user.name</code> and <code>user.email</code>. “not a git repository” → <code>cd</code> to the project. “nothing to commit” → nothing changed or not staged. “failed to push some refs … fetch first” → <code>git pull</code> then push. “detached HEAD” → <code>git switch main</code> (or <code>git switch -c name</code> to keep the work).'],
 ana='Soft, mixed and hard are three depths of rewinding a tape: keep everything ready, keep the edits, or erase.',
 cmd='<code>git reset --soft HEAD~1</code><br><code>git reset HEAD~1</code><br><code>git reflog</code><br><code>git reset --hard ID</code><p>--hard is destructive for uncommitted work.</p>',
 mis=[('Using --hard casually.','Prefer soft or mixed.'),('Resetting pushed commits.','Use revert.'),('Giving up on lost commits.','Look in reflog first.')],
 ex='Make a test commit, undo it with reset --soft, then recommit.',res='The file is staged again after reset --soft.',
 q=[('Which reset keeps changes staged?',['--soft','--hard','--mixed'],0,'Soft keeps them staged.'),('How do you find a “lost” commit?',['git reflog','git clone','git fetch'],0,'It records HEAD moves.'),('“fetch first” on push means…',['Pull before pushing','Delete repo','Reinstall'],0,'GitHub has newer commits.')],
 sm='Reset rewinds locally, reflog rescues, and revert is for shared history.',voc=[('reset','Move the branch to another commit'),('reflog','Log of HEAD movements'),('detached HEAD','HEAD on a commit, not a branch')],
 nxt='<b>Module 11 — Professional habits.</b>',svg=term(C3,ill),fig='Figure 1 · Illustration: reset and reflog')
